		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if el > maxLoad {
			maxLoad = el
		}
	}
	loadSpread := maxLoad - minLoad

	// Compute base composite scores from scorers
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Post-scoring: targeted adjustments
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()

		// 1. Queue-depth penalty: penalize instances far above minimum load
		//    This reduces p95 by preventing pile-on
		if loadSpread > 0 {
			excess := float64(el-minLoad) / float64(loadSpread+1)
			scores[snap.ID] *= (1.0 - 0.4*excess)
		}

		// 2. Hard penalty for deep queues (absolute threshold)
		if snap.QueueDepth > 3 {
			scores[snap.ID] *= 0.75
		}

		// 3. Cache hit rate bonus — helps cache_warmup workload
		scores[snap.ID] *= (1.0 + 0.15*snap.CacheHitRate)

		// 4. KV pressure penalty — avoid eviction-prone instances
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.8
		}
	}

